#include "attention.hpp"
#include <hip/hip_runtime.h>
#include <windows.h>
#include <psapi.h>
#include <fstream>
#include <iostream>
#include <sstream>
#include <cstring>
using namespace strata_ext;
namespace {
void ck(hipError_t e){if(e!=hipSuccess)throw std::runtime_error(hipGetErrorString(e));}
std::vector<std::vector<std::string>> table(const std::filesystem::path&p,size_t columns){std::ifstream f(p);if(!f)throw std::runtime_error("table open");std::vector<std::vector<std::string>>rows;std::string line;while(std::getline(f,line)){std::stringstream s(line);std::vector<std::string>r;std::string cell;while(std::getline(s,cell,'\t'))r.push_back(cell);if(r.size()!=columns)throw std::runtime_error("table columns");rows.push_back(r);}return rows;}
template<class T>std::vector<T> read(const std::filesystem::path&p,size_t count){if(count>SIZE_MAX/sizeof(T)||std::filesystem::file_size(p)!=count*sizeof(T))throw std::runtime_error("exact input bytes");artifact::FixtureView view{p,0,count*sizeof(T)};auto bytes=view.read_exact(0,count*sizeof(T));std::vector<T>v(count);if(count)std::memcpy(v.data(),bytes.data(),bytes.size());return v;}
void output(const std::filesystem::path&p,const deepseek41::KvTrace&t){if(!std::filesystem::create_directory(p))throw std::runtime_error("preserve prior outputs");std::ofstream index(p/"stages.tsv");for(const auto&[name,s]:t.stages){std::ofstream f(p/(name+".bin"),std::ios::binary);f.write((const char*)s.bytes.data(),s.bytes.size());if(!f)throw std::runtime_error("output write");index<<name<<'\t'<<s.dtype<<'\t'<<s.rows<<'\t'<<s.columns<<'\t'<<s.bytes.size()<<'\n';}}
unsigned state(){unsigned n=0;auto require=[&](bool value){if(!value)throw std::runtime_error("view assertion");++n;};auto rejects=[&](auto fn){try{fn();}catch(const std::exception&){++n;return;}throw std::runtime_error("view rejection missing");};deepseek41::AttentionIndexView v;v.writer=20;v.epoch=7;v.ratio=1;v.positions=2;v.decoded.resize(256);v.validate(24,7);++n;rejects([&]{v.validate(24,8);});v.writer=2;rejects([&]{v.validate(24,7);});v.writer=20;v.positions=3;rejects([&]{v.validate(24,7);});deepseek41::AttentionCandidates c;c.epoch=7;c.queries=1;c.positions=2;c.visible={1};c.mask={1,1};c.validate(7);++n;rejects([&]{c.validate(8);});c.writer=24;rejects([&]{c.validate(7);});c.writer=20;c.mask[0]=2;rejects([&]{c.validate(7);});require(n>=8);for(int writer:{2,8,14,20})require(deepseek41::index_candidate_pruning(writer)==(writer==20));rejects([&]{deepseek41::index_candidate_pruning(24);});return n;}
std::string escape(const std::string&s){std::string v;for(char c:s){if(c=='\\'||c=='"')v+='\\';v+=c;}return v;}
}
int main(int argc,char**argv){try{
 if(argc==2&&std::string(argv[1])=="--identity"){std::cout<<"{\"source_id\":\""<<T15_SOURCE_ID<<"\"}";return 0;}
 if(argc==2&&std::string(argv[1])=="--state"){std::cout<<"{\"state_assertions\":"<<state()<<"}";return 0;}
 if(argc!=10||std::string(argv[1])!="--run")throw std::runtime_error("--run PCI weights compression sources prefixes jobs input8 output");
 deepseek41::SourceSet sources;for(const auto&r:table(argv[5],5)){deepseek41::SourceFile f;f.shard_index=std::stoul(r[0]);f.original_size=std::stoull(r[1]);f.lfs_sha256=r[2];f.revision=r[3];f.original_path=r[4];if(sources.root.empty())sources.root=f.original_path.parent_path();sources.files.push_back(f);}
 std::vector<artifact::PrefixIndex>prefixes;std::string first;for(const auto&r:table(argv[6],2)){if(first.empty())first=r[1];prefixes.push_back(artifact::inspect_prefix(r[1],std::stoull(r[0])));}deepseek41::Artifact index(artifact::merge_prefixes(prefixes),deepseek41::inspect_metadata(first),sources);
 auto weights=[&](const char*path,size_t count){deepseek41::KvWeights out;for(const auto&r:table(path,4)){auto s=index.source_tensor(r[0]);if(s.span.absolute_offset!=std::stoull(r[1])||s.span.bytes!=std::stoull(r[2]))throw std::runtime_error("original source span");artifact::FixtureView view{r[3],s.span.absolute_offset,s.span.bytes};if(!out.emplace(r[0],deepseek41::KvWeight{s,view.read_exact(s.span.absolute_offset,s.span.bytes)}).second)throw std::runtime_error("duplicate weight");}if(out.size()!=count)throw std::runtime_error("weight coverage");return out;};
 auto w=weights(argv[3],28),compression=weights(argv[4],13);int count=0,device=-1;ck(hipGetDeviceCount(&count));for(int i=0;i<count;++i){char pci[64]={};ck(hipDeviceGetPCIBusId(pci,sizeof(pci),i));if(std::string(pci)==argv[2])device=i;}if(device<0)throw std::runtime_error("exact PCI absent");ck(hipSetDevice(device));hipDeviceProp_t prop{};ck(hipGetDeviceProperties(&prop,device));size_t before_free=0,before_total=0;auto before=hipMemGetInfo(&before_free,&before_total);ck(before);
 measurement::Identity id;id.fixture_sha256=T15_SOURCE_ID;id.asset_sha256=sources.files[8].lfs_sha256;id.bundle_sha256=T15_SOURCE_ID;id.request_id="t15";id.epoch=1;id.phase=measurement::Phase::Decode;auto input8=read<float>(argv[8],8*5120);std::filesystem::path root(argv[9]);if(!std::filesystem::create_directory(root))throw std::runtime_error("preserve output root");std::ostringstream report;bool firstjob=true;
 for(const auto&r:table(argv[7],8)){const auto&name=r[0];const auto&kind=r[1];size_t batch=std::stoull(r[2]),phase=std::stoull(r[3]),length=std::stoull(r[4]),rows=std::stoull(r[5]),columns=std::stoull(r[6]);deepseek41::KvTrace trace;deepseek41::KvFloats in;std::map<std::string,std::vector<int64_t>>integer;
 for(const auto&v:table(r[7],5)){size_t count=std::stoull(v[2])*std::stoull(v[3]);if(v[1]=="<f4")in.emplace(v[0],read<float>(v[4],count));else if(v[1]=="<i8")integer.emplace(v[0],read<int64_t>(v[4],count));else if(v[1]=="<i4"){auto x=read<int32_t>(v[4],count);integer.emplace(v[0],std::vector<int64_t>(x.begin(),x.end()));}else throw std::runtime_error("runtime input dtype");}
 if(kind=="projection")trace=deepseek41::attention_projection(in.at("input"),batch,w,id,argv[2]);else if(kind=="short")trace=deepseek41::attention_short(input8,length,phase,w,compression,id,argv[2]);else if(kind=="short_batch"){for(size_t c=0;c<batch;++c){auto part=deepseek41::attention_short(input8,length,(phase+c)%8,w,compression,id,argv[2]);for(auto&[n,v]:part.stages)trace.stages.emplace("c"+std::to_string(c)+"__"+n,std::move(v));trace.scratch_peak=std::max(trace.scratch_peak,part.scratch_peak);trace.primitive_peak=std::max(trace.primitive_peak,part.primitive_peak);if(part.cleanup_unknown)throw std::runtime_error("batch cleanup");}}else if(kind=="long")trace=deepseek41::attention_long(in,integer.at("visible"));else trace=deepseek41::attention_primitive(kind,in,integer,rows,columns);
 output(root/name,trace);if(!firstjob)report<<",";firstjob=false;report<<"{\"name\":\""<<name<<"\",\"stages\":"<<trace.stages.size()<<",\"primitive_peak\":"<<trace.primitive_peak<<",\"scratch_peak\":"<<trace.scratch_peak<<",\"cleanup_unknown\":"<<(trace.cleanup_unknown?"true":"false")<<"}";
 }
 HMODULE modules[1024];DWORD needed=0;if(!EnumProcessModules(GetCurrentProcess(),modules,sizeof(modules),&needed)||needed>sizeof(modules))throw std::runtime_error("loaded modules");std::cout<<"{\"source_id\":\""<<T15_SOURCE_ID<<"\",\"pci\":\""<<argv[2]<<"\",\"ordinal\":"<<device<<",\"arch\":\""<<prop.gcnArchName<<"\",\"state_assertions\":"<<state()<<",\"source_qualified\":false,\"jobs\":["<<report.str()<<"],\"before_status\":"<<int(before)<<",\"before_free\":"<<before_free<<",\"before_total\":"<<before_total<<",\"loaded_modules\":[";for(size_t i=0;i<needed/sizeof(HMODULE);++i){char path[32768];if(!GetModuleFileNameA(modules[i],path,sizeof(path)))throw std::runtime_error("loaded module path");if(i)std::cout<<",";std::cout<<"\""<<escape(path)<<"\"";}std::cout<<"]}";return 0;
 }catch(const std::exception&e){std::cerr<<e.what()<<std::endl;return 2;}}
